#include <iostream>
#include <string>
#include <vector>
using namespace std;

class Cat {
protected:
    string name;
    int age;
public:
    Cat(string n, int a) : name(n), age(a) {}
    string getName() { return name; }
    void greet() {
        cout << "我是" << name << "，今年 " << age << " 岁喵" << endl;
    }
};

class Kitten : public Cat {
protected:
    int days;
public:
    Kitten(string n, int a, int d) : Cat(n, a), days(d) {}
    void showDays() {
        cout << name << " 出生 " << days << " 天啦" << endl;
    }
};

int main() {
    int n = 0;
    cin >> n;

    vector<Cat> roster;
    for (int i = 0; i < n; i++) {
        int a = 0;
